int clamp(int val, int low, int high) {
    if (val < low) return low;
    if (val > high) return high;
    return val;
}

int calculate_area(int side) {
    return side * side;
}

int calculate_area(int width, int height) {
    return width * height;
}

int power_with_default(int base, int exp) {
    int res = 1;
    for (int i = 0; i < exp; i++) {
        res *= base;
    }
    return res;
}
