        std::cerr << "Assertion failed: " << expr << " at line " << line << "\n";
        std::exit(1);
    }
}
#define assert(expr) test_assert(static_cast<bool>(expr), #expr, __LINE__)

#include <optional>
#include "exercise.cpp"

int main() {
    auto pos = safe_parse_positive(42);
    assert(pos.has_value() && pos.value() == 42);

    auto neg = safe_parse_positive(-5);
    assert(!neg.has_value());

    assert(get_value_or_default(pos, 0) == 42);
    assert(get_value_or_default(neg, 99) == 99);

    std::cout << "Module 19 tests passed successfully.\n";
    return 0;
}
